<form wire:submit="save" class="space-y-5">
@if(($company&&$tab==='details')||(!$company&&$step===1))<flux:card class="grid gap-5 md:grid-cols-2"><flux:input wire:model="name" label="Company name" required/><flux:input wire:model="trading_name" label="Trading name"/><flux:input wire:model="code" label="Shortcode" required/><flux:switch wire:model="is_active" label="Active"/><flux:input wire:model="phone" label="Phone"/><flux:input wire:model="email" type="email" label="Email"/></flux:card>
@elseif(($company&&$tab==='addresses')||(!$company&&$step===2))<div class="grid gap-5 md:grid-cols-2"><flux:card><div class="mb-4 flex justify-between"><flux:heading>Head Office</flux:heading><flux:button type="button" size="sm" wire:click="address('head',null,{{ $office?->id??'null' }})">{{ ($office||$headOffice)?'Change':'Add' }}</flux:button></div>@php($h=$company&&$office?['site_name'=>$office->name,'site_address_line_1'=>$office->address_line_1,'site_address_line_2'=>$office->address_line_2,'site_town'=>$office->town,'site_county'=>$office->county,'site_postcode'=>$office->postcode]:$headOffice)@if($h)<address class="not-italic">@foreach(array_filter($h) as $line)<span class="block">{{ $line }}</span>@endforeach</address>@else<flux:text>No address added.</flux:text>@endif<flux:error name="headOffice"/></flux:card><flux:card><div class="mb-4 flex justify-between"><flux:heading>Depots</flux:heading><flux:button type="button" size="sm" wire:click="address('depot')">Add</flux:button></div><flux:table><flux:table.rows>@forelse($company?$depots:$draftDepots as $i=>$d)<flux:table.row><flux:table.cell>{{ $company?$d->name:$d['site_name'] }}</flux:table.cell><flux:table.cell align="end"><flux:button type="button" size="xs" icon="pencil" aria-label="Edit depot" wire:click="address('depot',{{ $company?'null':$i }},{{ $company?$d->id:'null' }})"/>@if($company)<flux:button type="button" size="xs" variant="danger" icon="trash" aria-label="Remove depot" wire:click="detachDepot({{ $d->id }})" wire:confirm="Remove this depot from the company?"/>@else<flux:button type="button" size="xs" variant="danger" icon="trash" aria-label="Remove depot" wire:click="removeDepot({{ $i }})"/>@endif</flux:table.cell></flux:table.row>@empty<flux:table.row><flux:table.cell>No depots.</flux:table.cell></flux:table.row>@endforelse</flux:table.rows></flux:table></flux:card></div>
@else<flux:card class="grid gap-5 md:grid-cols-2"><flux:input wire:model="logo" type="file" label="Logo"/><flux:input wire:model="document_prefix" label="Document prefix" required/><flux:input wire:model="brand_primary_color" type="color" label="Colour"/><flux:input wire:model="registration_number" label="Companies House"/><flux:input wire:model="vat_number" label="VAT"/>@if($company?->logo_path)<img src="{{ Storage::url($company->logo_path) }}" class="max-h-20" alt="Current company logo">@endif</flux:card>@endif
<div class="flex justify-between border-t pt-4"><div>@if(!$company&&$step>1)<flux:button type="button" wire:click="back">Back</flux:button>@endif</div><div>@if(!$company&&$step<3)<flux:button type="button" variant="primary" wire:click="next">Next</flux:button>@else<flux:button type="submit" variant="primary">Save</flux:button>@endif</div></div></form>
<flux:modal name="address" class="min-w-[34rem]"><div class="space-y-4"><flux:heading>{{ $addressType==='head'?'Head Office':'Depot' }}</flux:heading>@unless($creatingAddress)<flux:select wire:model.live="selectedSiteId" variant="combobox" clearable label="Find an existing address"><x-slot name="input"><flux:select.input wire:model="addressSearch" placeholder="Search name, address or postcode..."/></x-slot>@foreach($siteOptions as $option)<flux:select.option :value="$option->id">{{ $option->name }} — {{ $option->formattedAddress() }}</flux:select.option>@endforeach<flux:select.option.create wire:click="createAddress" min-length="3">Create "<span wire:text="addressSearch"></span>"</flux:select.option.create></flux:select><flux:text>Search existing sites first. Create a new address only when no match is available.</flux:text>@else<flux:input wire:model="site_name" label="Name"/><flux:input wire:model="site_address_line_1" label="Address line 1"/><flux:input wire:model="site_address_line_2" label="Address line 2"/><div class="grid grid-cols-3 gap-3"><flux:input wire:model="site_town" label="Town"/><flux:input wire:model="site_county" label="County"/><flux:input wire:model="site_postcode" label="Postcode"/></div><div class="flex justify-end"><flux:button type="button" variant="primary" wire:click="saveAddress">Save address</flux:button></div>@endunless</div></flux:modal></x-pages::settings.layout></section>
